import{_ as a,o as n,c as s,a6 as e}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"QUIC 传输层","description":"流与流 ID、变长整数、1-RTT/0-RTT 握手、连接 ID 与连接迁移。","frontmatter":{"title":"QUIC 传输层","description":"流与流 ID、变长整数、1-RTT/0-RTT 握手、连接 ID 与连接迁移。","source":"https://daiw.org/manual/http2-3/quic-transport"},"headers":[],"relativePath":"manual/computer-programming/http2-3/quic-transport.md","filePath":"manual/computer-programming/http2-3/quic-transport.md"}'),r={name:"manual/computer-programming/http2-3/quic-transport.md"};function l(d,t,o,p,i,c){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="quic-传输层" tabindex="-1">QUIC 传输层 <a class="header-anchor" href="#quic-传输层" aria-label="Permalink to &quot;QUIC 传输层&quot;">​</a></h1><p>流与流 ID、变长整数、1-RTT/0-RTT 握手、连接 ID 与连接迁移。</p><p>RFC 9000（传输）、9001（TLS）、9002（丢包检测与拥塞控制）。这一篇只讲 HTTP/3 用得到的部分。</p><h2 id="流" tabindex="-1">流 <a class="header-anchor" href="#流" aria-label="Permalink to &quot;流&quot;">​</a></h2><p>QUIC 原生提供<strong>多条独立的有序字节流</strong>，这是它与 TCP 的根本差异：</p><table tabindex="0"><thead><tr><th></th><th>TCP</th><th>QUIC</th></tr></thead><tbody><tr><td>抽象</td><td>一条有序字节流</td><td><strong>多条</strong>独立有序流</td></tr><tr><td>某段丢失时</td><td>全部后续数据阻塞</td><td><strong>只阻塞该流</strong></td></tr><tr><td>流量控制</td><td>连接级</td><td><strong>流级 + 连接级</strong></td></tr><tr><td>流的创建成本</td><td>一次握手</td><td>零（发第一个字节即创建）</td></tr></tbody></table><p>关键：QUIC <strong>知道</strong>每个字节属于哪个流。丢失的包只影响它所承载的那些流，其他流的数据照常交付给应用。</p><h3 id="流-id" tabindex="-1">流 ID <a class="header-anchor" href="#流-id" aria-label="Permalink to &quot;流 ID&quot;">​</a></h3><p>62 位变长整数，<strong>最低两位编码流的类型</strong>：</p><table tabindex="0"><thead><tr><th>低 2 位</th><th>类型</th><th>HTTP/3 用途</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>客户端发起，<strong>双向</strong></td><td><strong>请求流</strong>（一个请求/响应一条）</td></tr><tr><td><code>0x01</code></td><td>服务端发起，双向</td><td>h3 不使用</td></tr><tr><td><code>0x02</code></td><td>客户端发起，<strong>单向</strong></td><td>控制流、QPACK 编码器/解码器流</td></tr><tr><td><code>0x03</code></td><td>服务端发起，单向</td><td>控制流、QPACK 流、推送流</td></tr></tbody></table><p>对照 h2 的<a href="/Front2Full/manual/computer-programming/http2-3/h2-streams">流 ID 规则</a>（奇偶分客户端/服务端）：QUIC 多了「单向/双向」这一维，且 <strong>h2 的流 0（连接级）不存在</strong>——连接级控制在 QUIC 帧层或 h3 控制流上。</p><h2 id="变长整数" tabindex="-1">变长整数 <a class="header-anchor" href="#变长整数" aria-label="Permalink to &quot;变长整数&quot;">​</a></h2><p>QUIC 与 HTTP/3 的所有整数都用这套编码，<strong>首字节的高 2 位决定总长度</strong>：</p><table tabindex="0"><thead><tr><th>前 2 位</th><th>总字节数</th><th>可表示范围</th></tr></thead><tbody><tr><td><code>00</code></td><td>1</td><td>0 – 63</td></tr><tr><td><code>01</code></td><td>2</td><td>0 – 16383</td></tr><tr><td><code>10</code></td><td>4</td><td>0 – 2^30−1</td></tr><tr><td><code>11</code></td><td>8</td><td>0 – 2^62−1</td></tr></tbody></table><p>去掉前缀的剩余位即数值（大端）。例：<code>0x25</code> = <code>00100101</code> → 1 字节、值 37。</p><p>好处：小数值（绝大多数流 ID、帧类型、长度）只占 1 字节，同时保留了 62 位的表达上限。对照 h2 的<a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">定长 9 字节帧头</a>——h3 的帧头通常只有 <strong>2 字节</strong>（类型 1 + 长度 1）。</p><h2 id="握手" tabindex="-1">握手 <a class="header-anchor" href="#握手" aria-label="Permalink to &quot;握手&quot;">​</a></h2><h3 id="_1-rtt-首次连接" tabindex="-1">1-RTT（首次连接） <a class="header-anchor" href="#_1-rtt-首次连接" aria-label="Permalink to &quot;1-RTT（首次连接）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP + TLS 1.3:</span></span>
<span class="line"><span>  Client ──── SYN ──────────→          ┐</span></span>
<span class="line"><span>  Client ←─── SYN-ACK ───────          │ 1 RTT (TCP)</span></span>
<span class="line"><span>  Client ──── ACK + TLS CH ─→          ┘</span></span>
<span class="line"><span>  Client ←─── TLS SH+FIN ────          ┐ 1 RTT (TLS)</span></span>
<span class="line"><span>  Client ──── TLS FIN + 数据 →         ┘</span></span>
<span class="line"><span>  = 2 RTT 才能发第一个字节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>QUIC:</span></span>
<span class="line"><span>  Client ──── Initial(CH) ──→          ┐</span></span>
<span class="line"><span>  Client ←─── Initial(SH)+Handshake ─  │ 1 RTT</span></span>
<span class="line"><span>  Client ──── Handshake + 数据 ──────→  ┘</span></span>
<span class="line"><span>  = 1 RTT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>QUIC 把传输握手与 TLS 握手<strong>合并</strong>成一次——加密不是叠在传输之上，而是<strong>内建</strong>其中。</p><h3 id="_0-rtt-会话恢复" tabindex="-1">0-RTT（会话恢复） <a class="header-anchor" href="#_0-rtt-会话恢复" aria-label="Permalink to &quot;0-RTT（会话恢复）&quot;">​</a></h3><p>客户端持有上次连接的会话票据时，可在<strong>第一个包里就带应用数据</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Client ──── Initial + 0-RTT 数据 ──→   ← 零等待</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>重放风险</strong>：0-RTT 数据没有前向的握手确认，攻击者截获后可重放。因此：</p><ul><li>服务端 <strong>MUST NOT</strong> 在 0-RTT 中处理<strong>非幂等</strong>请求，或必须有去重机制。</li><li>拒绝时返回 <a href="/Front2Full/manual/computer-programming/http11/status-4xx"><code>425 Too Early</code></a>，客户端在握手完成后重发。</li><li>客户端 <strong>SHOULD</strong> 只在 0-RTT 中发送安全且幂等的请求（<code>GET</code>/<code>HEAD</code>）。</li></ul><h2 id="连接-id-与连接迁移" tabindex="-1">连接 ID 与连接迁移 <a class="header-anchor" href="#连接-id-与连接迁移" aria-label="Permalink to &quot;连接 ID 与连接迁移&quot;">​</a></h2><p><strong>TCP 连接由四元组标识</strong>（源 IP、源端口、目的 IP、目的端口）。手机从 WiFi 切到 4G，IP 变了 → 四元组变了 → <strong>连接必断</strong>，所有在途请求失败、需重新握手。</p><p>QUIC 改用 <strong>Connection ID（CID）</strong>：</p><ul><li>每个包携带 CID，接收方靠 CID 而非四元组查找连接。</li><li>客户端换网络后，用<strong>同一个 CID</strong> 从新地址继续发包，连接<strong>无缝延续</strong>——TLS 会话、拥塞状态、在途流全部保留。</li><li>服务端需通过<strong>路径验证</strong>（发送随机数据要求对方回应）确认新地址可达，防止地址欺骗与放大攻击。</li><li>为防跨路径追踪，双方会预先交换一组备用 CID，迁移时<strong>同时更换 CID</strong>，使旁观者无法把新旧路径关联起来。</li></ul><p>这是移动场景下 h3 最直观的用户可感收益。</p><h2 id="流量控制" tabindex="-1">流量控制 <a class="header-anchor" href="#流量控制" aria-label="Permalink to &quot;流量控制&quot;">​</a></h2><p>QUIC 自带两级流量控制，<a href="/Front2Full/manual/computer-programming/http2-3/h2-flow-control">h2 的那一层因此被删除</a>：</p><table tabindex="0"><thead><tr><th>级别</th><th>帧</th><th>传输参数（初始值）</th></tr></thead><tbody><tr><td>流级</td><td><code>MAX_STREAM_DATA</code></td><td><code>initial_max_stream_data_bidi_local/remote</code></td></tr><tr><td>连接级</td><td><code>MAX_DATA</code></td><td><code>initial_max_data</code></td></tr><tr><td>流数量</td><td><code>MAX_STREAMS</code></td><td><code>initial_max_streams_bidi/uni</code></td></tr></tbody></table><p>与 h2 的 <code>WINDOW_UPDATE</code> 的区别：QUIC 的帧传的是<strong>新的绝对上限</strong>，而非增量——重传时天然幂等，不会因重复计算而错乱。</p><h2 id="加密范围" tabindex="-1">加密范围 <a class="header-anchor" href="#加密范围" aria-label="Permalink to &quot;加密范围&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>QUIC 包结构:</span></span>
<span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ 首字节 + 版本 + CID (明文，供路由)      │  ← 中间件只能看到这些</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│ 包号 (头部保护加密)                    │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│ 载荷: 全部 QUIC 帧 (AEAD 加密)         │  ← ACK、流数据、流控全在这里</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>对照 TCP：序号、ACK、窗口、选项全部明文，中间件可读可改。QUIC 把它们全加密，带来：</p><ul><li><strong>抗僵化</strong>：中间件无法依赖内部结构，协议才能持续演进。</li><li><strong>抗窥探</strong>：观察者无法统计单个流的行为。</li><li><strong>代价</strong>：运维失去了传统抓包分析能力，需改用 <strong>qlog</strong>（端点导出的结构化日志）排障。</li></ul><h2 id="丢包恢复的改进" tabindex="-1">丢包恢复的改进 <a class="header-anchor" href="#丢包恢复的改进" aria-label="Permalink to &quot;丢包恢复的改进&quot;">​</a></h2><ul><li><strong>包号单调递增，重传用新包号</strong>——消除了 TCP 的「重传歧义」（收到 ACK 时无法区分确认的是原包还是重传包），RTT 估算因此更准。</li><li><strong>ACK 帧支持多达 256 个 ACK Range</strong>，比 TCP SACK 的 3–4 个 block 精确得多，能更快识别真实丢失。</li><li>拥塞控制在<strong>用户态</strong>，可按需换算法（默认类似 NewReno，普遍部署 BBR）。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h3-framing">HTTP/3 帧格式</a>。</p>`,41)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
